import * as AWS from "@alchemy.run/aws";
import * as Effect from "effect/Effect";

export default class JobFunction extends AWS.Lambda.Function<JobFunction>()(
  "JobFunction",
  { main: import.meta.url, memorySize: 512, functionUrl: true },
  Effect.gen(function* () {
    return {
      fetch: Effect.gen(function* () {
        return { jobId: crypto.randomUUID() };
      }),
    };
  }),
) {}

import { fileURLToPath } from "node:url";
import * as GCP from "@alchemy.run/gcp";
import * as Alchemy from "alchemy";
import * as Effect from "effect/Effect";

export default Alchemy.Stack(
  "GcpStaticSiteExample",
  { providers: GCP.providers(), state: Alchemy.localState() },
  Effect.gen(function* () {
    const site = yield* GCP.Storage.Upload("Site", {
      path: fileURLToPath(new URL("./site", import.meta.url)),
    });
    return site;
  }),
);

import { createRequire } from "node:module";

const packageVersion: string = createRequire(import.meta.url)("../../package.json").version;

const PROVIDER = "@alchemy.run/frontend-frameworks/nextjs/source";

export const describe = () => ({ provider: PROVIDER, version: packageVersion });

import { createRequire } from "node:module";

const readPackageVersion = (name: string): string | undefined => {
  try {
    const req = createRequire(import.meta.url);
    const version = (req(`${name}/package.json`) as { version?: string }).version;
    return typeof version === "string" && version.length > 0 ? version : undefined;
  } catch {
    return undefined;
  }
};

export const runtimeVersion = readPackageVersion("alchemy");

import { fileURLToPath } from "node:url";
import * as Effect from "effect/Effect";
import { watchImport } from "./watch.ts";

export const DEV_RELOAD_EXIT_CODE = 75;

const runNodeDevWatcher = Effect.fn(function* (entrypoint: string, root: string) {
  return yield* Effect.sync(() =>
    watchImport<{ readonly default?: unknown }>(entrypoint, {
      parentURL: import.meta.url,
      shouldInvalidate: (url) => {
        if (!url.startsWith("file:")) return false;
        const file = fileURLToPath(url);
        return file.startsWith(root);
      },
      onReload: () => {
        process.exitCode = DEV_RELOAD_EXIT_CODE;
      },
    }),
  );
});

export const dev = (entrypoint: string) => runNodeDevWatcher(entrypoint, process.cwd());

import { fileURLToPath } from "node:url";

const vibeLangLoaderFlags = (entry: string, isBun: boolean): Array<string> =>
  entry.endsWith(".ts")
    ? isBun
      ? ["--preload", fileURLToPath(import.meta.resolve("vibelang/bun"))]
      : ["--import", import.meta.resolve("vibelang/register")]
    : [];

export const childArgs = (entry: string, isBun: boolean): Array<string> => [...vibeLangLoaderFlags(entry, isBun), entry];

import * as Cloudflare from "@alchemy.run/cloudflare";
import * as Effect from "effect/Effect";

export default class Api extends Cloudflare.Worker<Api>()(
  "Api",
  {
    main: import.meta.url,
    observability: {
      enabled: true,
    },
  },
  Effect.gen(function* () {
    return { fetch: Effect.sync(() => ({ id: crypto.randomUUID() })) };
  }),
) {}
